import XCTest

/// Settings › Experimental › "Import a folder as a test catalog" (staff only; docs/architecture/TEST_CATALOGS.md). The
/// folder is generated by the app (`--test-catalog-fixture`: three small papers and one damaged file) instead of being
/// picked in Files, and a stand-in model reads (`--device-model-fake-reading`): the real models never run on this Mac.
/// The account is the Library v5 fixture (local scripted server, encrypted store, catalogs).
@MainActor
final class TestCatalogJourneyTests: XCTestCase {
    override func setUp() { continueAfterFailure = false }

    private func capture(_ app: XCUIApplication, _ name: String) {
        let attachment = XCTAttachment(screenshot: app.windows.firstMatch.screenshot())
        attachment.name = name; attachment.lifetime = .keepAlways; add(attachment)
    }

    private func launch(staff: Bool) -> XCUIApplication {
        XCUIDevice.shared.portraitWhereSupported()
        let app = XCUIApplication()
        app.launchArguments = ["--library-v5-fixture", "--device-model-download-fixture=ready", "-reader.deviceModel", "YES",
                               "--device-model-fake-reading", "--device-model-fake-step-ms=700", "--test-catalog-fixture",
                               "-appearance", "light"]
        if staff { app.launchArguments.append("--operator-fixture") }
        app.launch()
        app.show("library")
        return app
    }

    /// Settings, scrolled (gently) until the Experimental section's `row` shows.
    private func openExperimental(_ app: XCUIApplication, until row: XCUIElement) {
        app.openSettingsFromMenu()
        let list = app.collectionViews.firstMatch
        XCTAssertTrue(list.waitForExistence(timeout: 10), "Settings opens")
        for _ in 0..<12 where !(row.exists && row.isHittable) {
            list.swipeUp(velocity: .slow)
        }
    }

    private func wait(_ element: XCUIElement, label predicate: String, _ value: String, timeout: TimeInterval) -> Bool {
        let end = Date().addingTimeInterval(timeout)
        repeat {
            if element.exists, NSPredicate(format: "label \(predicate) %@", value).evaluate(with: element) { return true }
            usleep(150_000)
        } while Date() < end
        return false
    }

    func testReadersWhoAreNotStaffNeverSeeIt() {
        let app = launch(staff: false)
        let reader = app.switches["settings.deviceModel"]
        openExperimental(app, until: reader)
        XCTAssertTrue(reader.exists && reader.isHittable, "Settings has the on-device reader's row")
        XCTAssertFalse(app.buttons["settings.testCatalog.import"].exists, "Staff only")
        app.collectionViews.firstMatch.swipeUp(velocity: .slow)
        XCTAssertFalse(app.buttons["settings.testCatalog.import"].exists, "Staff only")
        capture(app, "Settings: a reader's Experimental section")
    }

    func testAFolderBecomesACatalogTheModelReadsOneAtATime() {
        let app = launch(staff: true)
        let importButton = app.buttons["settings.testCatalog.import"]
        openExperimental(app, until: importButton)
        XCTAssertTrue(importButton.waitForExistence(timeout: 10), "Staff see the action beside the on-device reader")
        XCTAssertTrue(app.switches["settings.deviceModel"].exists, "under the on-device reader's row")
        // Room under the row for the progress line and what wasn't read.
        app.collectionViews.firstMatch.swipeUp(velocity: .slow)
        if !importButton.isHittable { app.collectionViews.firstMatch.swipeDown(velocity: .slow) }
        capture(app, "Settings: the staff test catalog action")
        importButton.tap()

        let progress = app.staticTexts["settings.testCatalog.progress"]
        XCTAssertTrue(progress.waitForExistence(timeout: 15), "One progress line")
        XCTAssertTrue(wait(progress, label: "BEGINSWITH", "Reading", timeout: 30), "Every file is added, then read: \(progress.label)")
        XCTAssertTrue(progress.label.hasSuffix("of 4 with the on-device model"), progress.label)
        capture(app, "Reading with the on-device model")

        // Pause stops the reading under way; Resume reads that paper again and carries on.
        let pause = app.buttons["settings.testCatalog.pause"]
        XCTAssertEqual(pause.label, "Pause")
        pause.tap()
        XCTAssertTrue(wait(progress, label: "BEGINSWITH", "Paused", timeout: 5), progress.label)
        XCTAssertEqual(pause.label, "Resume")
        capture(app, "Paused")
        let pausedAt = progress.label
        sleep(3)
        XCTAssertEqual(progress.label, pausedAt, "Nothing is read while paused")
        pause.tap()

        // The damaged file failed when it was added; the three papers were still read.
        XCTAssertTrue(wait(progress, label: "==", "Done · 3 of 4 read", timeout: 90), progress.label)
        XCTAssertFalse(pause.exists, "Nothing to pause once done")
        let notRead = app.descendants(matching: .any)["settings.testCatalog.notRead"]
        XCTAssertTrue(notRead.waitForExistence(timeout: 5))
        notRead.tap()
        let broken = app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "Broken 2001")).firstMatch
        XCTAssertTrue(broken.waitForExistence(timeout: 5), "What couldn't be added is listed")
        XCTAssertTrue(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "couldn’t be opened")).firstMatch.exists
                      || broken.label.contains("couldn’t be opened"), "with its reason")
        capture(app, "Done, with the file that couldn't be added")

        // Importing the same folder again adds nothing twice and reads nothing again.
        importButton.tap()
        sleep(2)
        XCTAssertTrue(wait(progress, label: "BEGINSWITH", "Done · 3 of 4 read", timeout: 10), progress.label)

        // The Library shows the new catalog with the three papers, named after their files.
        let done = app.navigationBars.buttons["Done"]
        if done.exists { done.tap() }
        app.show("library")
        for title in ["Hartley 2014", "Okafor 2019", "Lindqvist 2022"] {
            let row = app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", title)).firstMatch
            XCTAssertTrue(row.waitForExistence(timeout: 10), "\(title) is in the test catalog")
        }
        XCTAssertFalse(app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", "Attention Is All You Need")).firstMatch.exists,
                       "The test catalog holds only the folder's papers")
        capture(app, "Library: the test catalog")
    }
}
